#!/bin/bash
# Push the extracted boundary frames to their presigned slots.
cd "$(dirname "$0")/frames" || exit 1

put () {
  local file="$1"; shift
  local url="$1"
  code=$(curl -s -o /dev/null -w '%{http_code}' -X PUT -H "Content-Type: image/png" --data-binary "@$file" "$url")
  printf '%-22s %s\n' "$file" "$code"
}

